DO $$
DECLARE
  locked boolean := false;
BEGIN
  WHILE NOT locked LOOP
    BEGIN
      LOCK TABLE orders IN ACCESS EXCLUSIVE MODE NOWAIT;
      locked := true;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.1);
    END;
  END LOOP;
END;
$$;
